package io.fireflysoftware.common.config.core.persistence.documentissuer;

import io.fireflysoftware.common.config.core.authority.*;
import io.fireflysoftware.common.config.core.services.documentissuer.impl.DocumentIssuerServiceImpl;
import io.fireflysoftware.common.config.interfaces.documentissuer.DocumentIssuerContracts.*;
import org.fireflyframework.core.transaction.RootTransactionException;
import org.junit.jupiter.api.Test;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.HashMap;
import java.time.ZoneOffset;
import java.nio.charset.StandardCharsets;
import static org.junit.jupiter.api.Assertions.*;

class DocumentIssuerServiceTest {
    static Prepare request(){var t=DocumentIssuerTransactionTest.TENANT;var now=DocumentIssuerTransactionTest.NOW.toEpochMilli();var source=new SourceSnapshot(t,1,"10000000-0000-4000-8000-000000000005",1,2,"tenant","Tenant",true,true,"https://assets.example/logo.svg","#123456","Footer");return new Prepare("10000000-0000-4000-8000-000000000004","10000000-0000-4000-8000-000000000003",0,new Definition("10000000-0000-4000-8000-000000000002",1,"DEPOSIT_DOCS","Tenant Documents","docs@example.test",List.of(new Use(Purpose.DEPOSIT_ACCOUNT_ENROLLMENT,"ACCOUNT_AGREEMENT","en-US")),source,now-1000,now+60000));}
    static byte[] original(){try{return new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsBytes(request());}catch(Exception e){throw new AssertionError(e);}}
    @Test void realServiceCannotPrepareFromMissingCurrentOwnerSource(){var f=new DocumentIssuerTransactionTest();var a=f.authority();var d=new DocumentIssuerTransactionTest.Driver();var service=new DocumentIssuerServiceImpl(a,new DocumentIssuerTransaction(d,a,f.clock,f.nanos));assertThrows(RootTransactionException.class,()->service.prepare(DocumentIssuerTransactionTest.TENANT,original()).block());assertEquals(1,d.rollbacks);assertEquals(0,d.commits);assertTrue(d.sql.stream().anyMatch(sql->sql.contains("cfg_document_issuer_current_source")));assertTrue(d.sql.stream().noneMatch(sql->sql.startsWith("INSERT")));}
    @Test void malformedSourceIntentNeverAcquiresAnyConnection(){var f=new DocumentIssuerTransactionTest();var a=f.authority();var d=new DocumentIssuerTransactionTest.Driver();var service=new DocumentIssuerServiceImpl(a,new DocumentIssuerTransaction(d,a,f.clock,f.nanos));assertThrows(IllegalArgumentException.class,()->service.prepare(DocumentIssuerTransactionTest.TENANT,"{}".getBytes(StandardCharsets.UTF_8)).block());assertEquals(0,d.creates);}
    @Test void crossTenantSourceRequestRefusesBeforeAcquisition(){var f=new DocumentIssuerTransactionTest();var a=f.authority();var d=new DocumentIssuerTransactionTest.Driver();var service=new DocumentIssuerServiceImpl(a,new DocumentIssuerTransaction(d,a,f.clock,f.nanos));assertThrows(IllegalArgumentException.class,()->service.prepare("10000000-0000-4000-8000-000000000009",original()).block());assertEquals(0,d.creates);}
    static Map<String,Object> sourceRow(){var s=request().definition().source();return Map.ofEntries(Map.entry("branding_id",UUID.fromString(s.brandingId())),Map.entry("tenant_id",UUID.fromString(s.tenantId())),Map.entry("tenant_version",s.tenantVersion()),Map.entry("branding_version",s.brandingVersion()),Map.entry("source_generation",s.sourceGeneration()),Map.entry("tenant_code",s.tenantCode()),Map.entry("tenant_name",s.tenantName()),Map.entry("tenant_active",s.tenantActive()),Map.entry("branding_active",s.brandingActive()),Map.entry("logo_url",s.logoUrl()),Map.entry("primary_color",s.primaryColor()),Map.entry("footer_text",s.footerText()));}
    @Test void realMappedSourcePreparationWritesFiveAtomicRowsAndOnlyPreparedReceipt(){var f=new DocumentIssuerTransactionTest();var a=f.authority();var d=new DocumentIssuerTransactionTest.Driver();d.sourceData=sourceRow();var service=new DocumentIssuerServiceImpl(a,new DocumentIssuerTransaction(d,a,f.clock,f.nanos));var receipt=service.prepare(DocumentIssuerTransactionTest.TENANT,original()).block();assertNotNull(receipt);assertEquals(State.PREPARED,receipt.state());assertEquals(request().publicationId(),receipt.publicationId());assertEquals(1,receipt.generation());assertEquals(5,d.sql.stream().filter(sql->sql.startsWith("INSERT ")).count());assertEquals(1,d.commits);assertEquals(0,d.rollbacks);assertEquals(1,d.closes);}
    static byte[] decision(){var p=request();var value=new Decision(p.actionId(),p.definition().issuerId(),p.publicationId(),1,DocumentIssuerCodec.definitionDigest(p.definition()),1,"APPROVED");try{return new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsBytes(value);}catch(Exception error){throw new AssertionError(error);}}
    @Test void missingRetainedPublicationCannotProducePublishedReceipt(){var f=new DocumentIssuerTransactionTest();var a=f.authority();var d=new DocumentIssuerTransactionTest.Driver();var service=new DocumentIssuerServiceImpl(a,new DocumentIssuerTransaction(d,a,f.clock,f.nanos));assertThrows(RootTransactionException.class,()->service.publish(DocumentIssuerTransactionTest.TENANT,decision()).block());assertEquals(1,d.rollbacks);assertEquals(0,d.commits);assertTrue(d.sql.stream().anyMatch(sql->sql.contains("cfg_document_issuer_revision")));assertTrue(d.sql.stream().noneMatch(sql->sql.startsWith("INSERT ")));}
    @Test void bothDecisionEntryPointsRejectMalformedInputBeforeAcquisition(){var f=new DocumentIssuerTransactionTest();var a=f.authority();var d=new DocumentIssuerTransactionTest.Driver();var service=new DocumentIssuerServiceImpl(a,new DocumentIssuerTransaction(d,a,f.clock,f.nanos));assertThrows(IllegalArgumentException.class,()->service.publish(DocumentIssuerTransactionTest.TENANT,"{}".getBytes(StandardCharsets.UTF_8)).block());assertThrows(IllegalArgumentException.class,()->service.revoke(DocumentIssuerTransactionTest.TENANT,"{}".getBytes(StandardCharsets.UTF_8)).block());assertEquals(0,d.creates);}
    static Map<String,Object> revisionRow(String maker){var p=request();return Map.ofEntries(Map.entry("publication_id",UUID.fromString(p.publicationId())),Map.entry("tenant_id",UUID.fromString(p.definition().source().tenantId())),Map.entry("issuer_id",UUID.fromString(p.definition().issuerId())),Map.entry("revision",1L),Map.entry("definition_json",DocumentIssuerCodec.definitionJson(p.definition())),Map.entry("definition_digest",DocumentIssuerCodec.definitionDigest(p.definition())),Map.entry("source_generation",2L),Map.entry("maker_issuer","https://identity.example"),Map.entry("maker_subject",maker),Map.entry("prepared_at",DocumentIssuerTransactionTest.NOW.atOffset(ZoneOffset.UTC)));}
    static Map<String,Object> controlRow(){var p=request();return Map.of("issuer_id",UUID.fromString(p.definition().issuerId()),"tenant_id",UUID.fromString(p.definition().source().tenantId()),"publication_id",UUID.fromString(p.publicationId()),"revision",1L,"generation",1L,"state","PREPARED","source_generation",2L);}
    @Test void distinctCheckerPublishesThroughActualMappedDecisionAndCas(){var f=new DocumentIssuerTransactionTest();var a=f.authority();var d=new DocumentIssuerTransactionTest.Driver();d.sourceData=sourceRow();d.revisionData=revisionRow("maker");d.controlData=controlRow();var service=new DocumentIssuerServiceImpl(a,new DocumentIssuerTransaction(d,a,f.clock,f.nanos));var receipt=service.publish(DocumentIssuerTransactionTest.TENANT,decision()).block();assertNotNull(receipt);assertEquals(State.PUBLISHED,receipt.state());assertEquals(2,receipt.generation());assertEquals(4,d.sql.stream().filter(sql->sql.startsWith("INSERT ")).count());assertEquals(1,d.sql.stream().filter(sql->sql.startsWith("UPDATE ")).count());assertEquals(1,d.commits);assertEquals(0,d.rollbacks);}
    @Test void makerCannotPublishOwnRetainedRevisionDespiteCurrentCallerPermission(){var f=new DocumentIssuerTransactionTest();var a=f.authority();var d=new DocumentIssuerTransactionTest.Driver();d.sourceData=sourceRow();d.revisionData=revisionRow("checker");d.controlData=controlRow();var service=new DocumentIssuerServiceImpl(a,new DocumentIssuerTransaction(d,a,f.clock,f.nanos));assertThrows(RootTransactionException.class,()->service.publish(DocumentIssuerTransactionTest.TENANT,decision()).block());assertTrue(d.sql.stream().anyMatch(sql->sql.contains("cfg_document_issuer_current_source")));assertTrue(d.sql.stream().noneMatch(sql->sql.startsWith("INSERT ")));assertEquals(1,d.rollbacks);assertEquals(0,d.commits);}
    @Test void changedSourceGenerationPreventsPublicationBeforeAnyWrite(){var f=new DocumentIssuerTransactionTest();var a=f.authority();var d=new DocumentIssuerTransactionTest.Driver();d.sourceData=new HashMap<>(sourceRow());d.sourceData.put("source_generation",3L);d.revisionData=revisionRow("maker");d.controlData=controlRow();var service=new DocumentIssuerServiceImpl(a,new DocumentIssuerTransaction(d,a,f.clock,f.nanos));assertThrows(RootTransactionException.class,()->service.publish(DocumentIssuerTransactionTest.TENANT,decision()).block());assertTrue(d.sql.stream().anyMatch(sql->sql.contains("cfg_document_issuer_current_source")));assertTrue(d.sql.stream().noneMatch(sql->sql.startsWith("INSERT ")));assertEquals(1,d.rollbacks);assertEquals(0,d.commits);}
    static Reference reference(){var p=request();return new Reference(p.definition().source().tenantId(),p.definition().issuerId(),p.publicationId(),1,DocumentIssuerCodec.definitionDigest(p.definition()),p.definition().uses().getFirst());}
    @Test void currentHasNoCommandPoolFallbackWhenDedicatedReaderIsAbsent(){var f=new DocumentIssuerTransactionTest();var a=f.authority();var d=new DocumentIssuerTransactionTest.Driver();var service=new DocumentIssuerServiceImpl(a,new DocumentIssuerTransaction(d,a,f.clock,f.nanos));assertThrows(IllegalStateException.class,()->service.current(reference()).block());assertEquals(0,d.creates);}
    @Test void missingPublishedReferenceIsReadOnlyUnavailable(){var f=new DocumentIssuerTransactionTest();var a=f.authority();var command=new DocumentIssuerTransactionTest.Driver();var reader=new DocumentIssuerTransactionTest.Driver();var service=new DocumentIssuerServiceImpl(a,new DocumentIssuerTransaction(command,a,f.clock,f.nanos),new DocumentIssuerTransaction(reader,a,f.clock,f.nanos));assertThrows(RootTransactionException.class,()->service.current(reference()).block());assertEquals(0,command.creates);assertEquals(1,reader.rollbacks);assertTrue(reader.sql.contains("SET TRANSACTION READ ONLY"));assertTrue(reader.sql.stream().noneMatch(sql->sql.startsWith("INSERT ")));}
    @Test void malformedCurrentReferenceNeverAcquiresAnyPool(){var f=new DocumentIssuerTransactionTest();var a=f.authority();var command=new DocumentIssuerTransactionTest.Driver();var reader=new DocumentIssuerTransactionTest.Driver();var service=new DocumentIssuerServiceImpl(a,new DocumentIssuerTransaction(command,a,f.clock,f.nanos),new DocumentIssuerTransaction(reader,a,f.clock,f.nanos));var r=reference();assertThrows(IllegalArgumentException.class,()->service.current(new Reference(r.tenantId(),r.issuerId(),r.publicationId(),0,r.definitionDigest(),r.use())).block());assertEquals(0,command.creates);assertEquals(0,reader.creates);}
    @Test void nativeWindowCannotOutliveRetainedBusinessCutoffOnPublish(){
        var f=new DocumentIssuerTransactionTest();var a=f.authority();var d=new DocumentIssuerTransactionTest.Driver();
        var original=request().definition();var shortDefinition=new Definition(original.issuerId(),1,original.issuerCode(),original.displayName(),original.contactEmail(),original.uses(),original.source(),original.effectiveFromEpochMillis(),DocumentIssuerTransactionTest.NOW.plusMillis(100).toEpochMilli());
        d.revisionData=new HashMap<>(revisionRow("maker"));d.revisionData.put("definition_json",DocumentIssuerCodec.definitionJson(shortDefinition));d.revisionData.put("definition_digest",DocumentIssuerCodec.definitionDigest(shortDefinition));d.controlData=controlRow();d.sourceData=sourceRow();
        var decision=new Decision(request().actionId(),original.issuerId(),request().publicationId(),1,DocumentIssuerCodec.definitionDigest(shortDefinition),1,"APPROVED");
        byte[] body;try{body=new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsBytes(decision);}catch(Exception error){throw new AssertionError(error);}
        var service=new DocumentIssuerServiceImpl(a,new DocumentIssuerTransaction(d,a,f.clock,f.nanos));
        assertThrows(RootTransactionException.class,()->service.publish(DocumentIssuerTransactionTest.TENANT,body).block());
        assertEquals(0,d.commits);assertEquals(1,d.rollbacks);assertTrue(d.sql.stream().noneMatch(sql->sql.startsWith("INSERT ")));
    }
    static Map<String,Object> publishedDecisionRow(){var p=request();return Map.ofEntries(Map.entry("action_id",new UUID(0,8)),Map.entry("tenant_id",UUID.fromString(p.definition().source().tenantId())),Map.entry("issuer_id",UUID.fromString(p.definition().issuerId())),Map.entry("publication_id",UUID.fromString(p.publicationId())),Map.entry("revision",1L),Map.entry("operation","PUBLISH"),Map.entry("definition_digest",DocumentIssuerCodec.definitionDigest(p.definition())),Map.entry("actor_issuer","https://identity.example"),Map.entry("actor_subject","checker"),Map.entry("recorded_at",DocumentIssuerTransactionTest.NOW.atOffset(ZoneOffset.UTC)));}
    @Test void currentUsesScopedLookupThenTwoProtectedReadOnlyRootsWithEarliestHorizon(){
        var f=new DocumentIssuerTransactionTest();var a=f.authority();var command=new DocumentIssuerTransactionTest.Driver();var reader=new DocumentIssuerTransactionTest.Driver();
        reader.sourceData=sourceRow();reader.revisionData=revisionRow("maker");reader.controlData=new HashMap<>(controlRow());reader.controlData.put("state","PUBLISHED");reader.controlData.put("generation",2L);reader.decisionData=publishedDecisionRow();
        var service=new DocumentIssuerServiceImpl(a,new DocumentIssuerTransaction(command,a,f.clock,f.nanos),new DocumentIssuerTransaction(reader,a,f.clock,f.nanos));
        var result=service.current(reference()).block();assertNotNull(result);assertEquals(2,result.generation());assertEquals(request().definition(),result.definition());
        assertEquals(DocumentIssuerTransactionTest.NOW.plusMillis(3998).toEpochMilli(),result.nativeUntilEpochMillis());assertEquals(DocumentIssuerTransactionTest.NOW.plusMillis(3997).toEpochMilli(),result.effectiveUntilEpochMillis());
        assertEquals(0,command.creates);assertEquals(3,reader.creates);assertEquals(3,reader.commits);assertEquals(3,reader.closes);assertEquals(3,reader.sql.stream().filter(sql->sql.equals("SET TRANSACTION READ ONLY")).count());
        assertTrue(reader.sql.stream().noneMatch(sql->sql.startsWith("INSERT ")||sql.startsWith("UPDATE ")));
    }
    @Test void publicCurrentResolvesIssuerFromActualPublicationMetadata(){
        var f=new DocumentIssuerTransactionTest();var a=f.authority();var command=new DocumentIssuerTransactionTest.Driver();var reader=new DocumentIssuerTransactionTest.Driver();reader.sourceData=sourceRow();reader.revisionData=revisionRow("maker");reader.controlData=new HashMap<>(controlRow());reader.controlData.put("state","PUBLISHED");reader.controlData.put("generation",2L);reader.decisionData=publishedDecisionRow();
        var service=new DocumentIssuerServiceImpl(a,new DocumentIssuerTransaction(command,a,f.clock,f.nanos),new DocumentIssuerTransaction(reader,a,f.clock,f.nanos));var r=reference();
        var result=service.current(new PublicationReference(r.tenantId(),r.publicationId(),r.revision(),r.definitionDigest(),r.use())).block();assertNotNull(result);assertEquals(r.issuerId(),result.reference().issuerId());assertEquals(0,command.creates);
    }
}
